-- wave251b (15/10/26): the direct messages moved into their own function, social-dms; the comments say so.
comment on table public.social_threads is 'wave251: a Messenger or Instagram conversation between Welfare Avenue''s Page or Instagram account and one person (the Content Studio''s Messages). Written by social-dms (dm_sync, dm_reply and the dm_* actions) with the service key; read by the marketing team and admins (wa225_marketing, wa225_publisher).';
comment on table public.social_messages is 'wave251: the messages of a social_threads conversation, the person''s and ours (from_us), read through Meta''s Graph API (conversations, messages). Written by social-dms with the service key; read by the marketing team and admins.';
comment on table public.meta_events is 'wave250: each change Meta sent to the meta-events webhook (object page, instagram or whatsapp_business_account; field feed, messages, mention, leadgen, comments, mentions, statuses). A hint only: meta-events re-reads the object through the Graph API before the Hub changes. value is the change without its text fields (no message or comment text kept here), cleared after 60 days (meta-events prune). Written by meta-events with the service key; admins read it (Studio > Connections).';
-- the weekly clearing of old event values (Mondays 08:30 UTC)
select cron.schedule('wa-meta-events-prune', '30 8 * * 1', $c$select public.call_edge('meta-events', '{"action":"prune"}'::jsonb)$c$);
